import{_ as a,o as t,c as o,a7 as r}from"./chunks/framework.FWlv_suP.js";const h=JSON.parse('{"title":"MetroPocket Data Deletion","description":"Official Data Deletion for MetroPocket.","frontmatter":{"title":"MetroPocket Data Deletion","description":"Official Data Deletion for MetroPocket.","navbar":false,"sidebar":false,"aside":false,"outline":false,"footer":false,"prev":false,"next":false,"editLink":false,"lastUpdated":false,"pageClass":"standalone-policy"},"headers":[],"relativePath":"data-deletion/metro-pocket.md","filePath":"data-deletion/metro-pocket.md"}'),l={name:"data-deletion/metro-pocket.md"};function n(s,e,i,d,c,p){return t(),o("div",null,[...e[0]||(e[0]=[r('<h1 id="delete-metropocket-data" tabindex="-1">Delete MetroPocket Data <a class="header-anchor" href="#delete-metropocket-data" aria-label="Permalink to &quot;Delete MetroPocket Data&quot;">​</a></h1><p>MetroPocket has no online account or developer-operated cloud database. App data is stored locally on your device or in your browser.</p><h2 id="remove-one-data-pack" tabindex="-1">Remove one data pack <a class="header-anchor" href="#remove-one-data-pack" aria-label="Permalink to &quot;Remove one data pack&quot;">​</a></h2><p>Open <strong>Offline Data</strong> in MetroPocket and remove the installed pack you no longer want. This deletes that pack&#39;s local copy and metadata.</p><h2 id="remove-saved-train-schedules" tabindex="-1">Remove saved train schedules <a class="header-anchor" href="#remove-saved-train-schedules" aria-label="Permalink to &quot;Remove saved train schedules&quot;">​</a></h2><p>Open <strong>Settings → Train Data</strong> and choose <strong>Delete All Train Data</strong> to remove every saved train schedule from the app. This does not remove Metro or TV packs. A Train backup exported outside the app remains in the location you chose until you delete that file separately.</p><h2 id="remove-all-local-data" tabindex="-1">Remove all local data <a class="header-anchor" href="#remove-all-local-data" aria-label="Permalink to &quot;Remove all local data&quot;">​</a></h2><ul><li><strong>Android:</strong> Clear MetroPocket&#39;s storage in Android settings or uninstall the app. Android backup and device transfer are disabled for its private data.</li><li><strong>Web/PWA:</strong> Clear site data for the MetroPocket website in your browser. This removes stored packs, preferences, train schedules, and cached app files. Uninstalling a PWA shortcut alone may not clear browser site data.</li></ul><p>Your browser may also evict stored data automatically. Removing local data does not delete support emails you sent. To request deletion of support correspondence held by the developer, email <a href="mailto:anand.official.in@gmail.com" target="_blank" rel="noreferrer">anand.official.in@gmail.com</a>. The developer cannot remotely delete data that remains only on your device.</p>',9)])])}const f=a(l,[["render",n]]);export{h as __pageData,f as default};
